package main

import (
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type SalesRec struct { // 01 SALES-REC, 12 bytes
	SrId    string          // PIC X(4) @0 len=4
	SrSales decimal.Decimal // PIC 9(6)V99 @4 len=8
}

type TierTable struct { // 01 TIER-TABLE, 44 bytes
	TierEntry struct { // group @0 len=11
		TierLimit decimal.Decimal // PIC 9(6)V99 @0 len=8
		TierRate  decimal.Decimal // PIC 9V99 @8 len=3
	}
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N" // PIC X len=1 = "N"
var WsIdx int64 = 0        // PIC 9 len=1 = 0
var WsTier int64 = 0       // PIC 9 len=1 = 0
var WsComm decimal.Decimal // PIC 9(6)V99 len=8 = 0
var WsTotal decimal.Decimal // PIC 9(9)V99 len=11 = 0
var WsCount int64 = 0       // PIC 9(3) len=3 = 0
var WsSalesEd string        // PIC ZZZ,ZZ9.99 len=10
var WsRateEd string         // PIC 9.99 len=4
var WsCommEd string         // PIC ZZZ,ZZ9.99 len=10
var WsTotalEd string        // PIC ZZZ,ZZZ,ZZ9.99 len=14

var curRec SalesRec

var TierLimits [5]decimal.Decimal
var TierRates [5]decimal.Decimal

var salesLines []string
var salesPos int

func pow10Int64(n int) int64 {
	var r int64 = 1
	for i := 0; i < n; i++ {
		r *= 10
	}
	return r
}

func truncatePic(v decimal.Decimal, intDigits int, scale int) decimal.Decimal {
	shifted := v.Shift(int32(scale)).Truncate(0)
	totalDigits := intDigits + scale
	pow10 := decimal.NewFromInt(1).Shift(int32(totalDigits))
	if shifted.IsNegative() {
		abs := shifted.Abs().Mod(pow10)
		if abs.IsZero() {
			return decimal.New(0, int32(-scale))
		}
		return abs.Neg().Shift(int32(-scale))
	}
	m := shifted.Mod(pow10)
	return m.Shift(int32(-scale))
}

func formatEdited(v decimal.Decimal, pic string) string {
	intPic := pic
	decPic := ""
	if idx := strings.Index(pic, "."); idx >= 0 {
		intPic = pic[:idx]
		decPic = pic[idx+1:]
		_ = decPic
	}
	decDigits := 0
	if strings.Contains(pic, ".") {
		part := pic[strings.Index(pic, ".")+1:]
		for _, ch := range part {
			if ch == 'Z' || ch == '9' {
				decDigits++
			}
		}
	}
	intDigits := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			intDigits++
		}
	}
	t := v.Truncate(int32(decDigits))
	abs := t.Abs()
	shifted := abs.Shift(int32(decDigits)).Truncate(0)
	shiftInt := shifted.IntPart()
	var fracInt int64
	var intInt int64
	if decDigits > 0 {
		powScale := pow10Int64(decDigits)
		fracInt = shiftInt % powScale
		intInt = shiftInt / powScale
	} else {
		intInt = shiftInt
	}
	powInt := pow10Int64(intDigits)
	if powInt != 0 {
		intInt = intInt % powInt
	}
	intStr := fmt.Sprintf("%0*d", intDigits, intInt)
	fracStr := ""
	if decDigits > 0 {
		fracStr = fmt.Sprintf("%0*d", decDigits, fracInt)
	}
	var b strings.Builder
	p := 0
	suppressed := true
	for _, ch := range intPic {
		if ch == ',' {
			if suppressed {
				b.WriteByte(' ')
			} else {
				b.WriteByte(',')
			}
		} else if ch == 'Z' {
			d := intStr[p]
			p++
			if suppressed && d == '0' {
				b.WriteByte(' ')
			} else {
				b.WriteByte(d)
				suppressed = false
			}
		} else if ch == '9' {
			d := intStr[p]
			p++
			b.WriteByte(d)
			suppressed = false
		} else {
			b.WriteByte(byte(ch))
		}
	}
	res := b.String()
	if strings.Contains(pic, ".") {
		res = res + "." + fracStr
	}
	return res
}

func parseSales(s string) decimal.Decimal {
	clean := strings.ReplaceAll(s, " ", "")
	if clean == "" {
		return decimal.Zero
	}
	if strings.Contains(clean, ".") || strings.Contains(clean, ",") {
		d, err := decimal.NewFromString(clean)
		if err != nil {
			return decimal.Zero
		}
		return d
	}
	n, err := strconv.ParseInt(clean, 10, 64)
	if err != nil {
		return decimal.Zero
	}
	return decimal.New(n, -2)
}

func InitPara() {
	TierLimits[1] = decimal.RequireFromString("1000.00")
	TierRates[1] = decimal.RequireFromString("2.50")
	TierLimits[2] = decimal.RequireFromString("5000.00")
	TierRates[2] = decimal.RequireFromString("4.00")
	TierLimits[3] = decimal.RequireFromString("20000.00")
	TierRates[3] = decimal.RequireFromString("5.50")
	TierLimits[4] = decimal.RequireFromString("999999.99")
	TierRates[4] = decimal.RequireFromString("7.25")
}

func ReadPara() {
	if salesPos >= len(salesLines) {
		WsEofFlag = "Y"
		return
	}
	raw := salesLines[salesPos]
	salesPos++
	if len(raw) < 12 {
		raw = raw + strings.Repeat(" ", 12-len(raw))
	} else if len(raw) > 12 {
		raw = raw[:12]
	}
	curRec.SrId = raw[0:4]
	curRec.SrSales = parseSales(raw[4:12])
}

func ProcessPara() {
	WsTier = 0
	WsIdx = 1
	for !(WsIdx > 4 || WsTier > 0) {
		if curRec.SrSales.Cmp(TierLimits[WsIdx]) <= 0 {
			WsTier = WsIdx
		}
		WsIdx++
	}
	rate := TierRates[WsTier]
	tmp := curRec.SrSales.Mul(rate).Shift(-2)
	rounded := tmp.Round(2)
	WsComm = truncatePic(rounded, 6, 2)
	WsTotal = truncatePic(WsTotal.Add(WsComm), 9, 2)
	WsCount = (WsCount + 1) % 1000
	WsSalesEd = formatEdited(curRec.SrSales, "ZZZ,ZZ9.99")
	WsRateEd = formatEdited(rate, "9.99")
	WsCommEd = formatEdited(WsComm, "ZZZ,ZZ9.99")
	tierStr := fmt.Sprintf("%01d", WsTier)
	line := curRec.SrId + " T" + tierStr + " " + WsSalesEd + " " + WsRateEd + "% " + WsCommEd
	os.Stdout.WriteString(line + "\n")
	ReadPara()
}

func SummaryPara() {
	WsTotalEd = formatEdited(WsTotal, "ZZZ,ZZZ,ZZ9.99")
	cntStr := fmt.Sprintf("%03d", WsCount)
	line := "REPS: " + cntStr + " TOTAL: " + WsTotalEd
	os.Stdout.WriteString(line + "\n")
}

func MainPara() {
	InitPara()
	data, err := os.ReadFile("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err.Error())
		os.Exit(1)
	}
	if len(data) == 0 {
		salesLines = nil
	} else {
		content := string(data)
		parts := strings.Split(content, "\n")
		if strings.HasSuffix(content, "\n") {
			parts = parts[:len(parts)-1]
		}
		salesLines = make([]string, 0, len(parts))
		for _, p := range parts {
			if strings.HasSuffix(p, "\r") {
				p = p[:len(p)-1]
			}
			salesLines = append(salesLines, p)
		}
	}
	salesPos = 0
	ReadPara()
	for WsEofFlag != "Y" {
		ProcessPara()
	}
	SummaryPara()
}

func main() {
	MainPara()
}
